import { createRouter, createWebHistory } from 'vue-router'
import ContainerPage from '@/views/ContainerPage.vue'  // 你的容器管理页面
import NetworkPage from '@/views/NetworkPage.vue'      // 网络管理页面（可以先创建空页面）
import MainLayout from '@/views/MainLayout.vue'

const routes = [
    {
        path: '/',
        name: 'container',
        component: ContainerPage,
    },
    {
        path: '/network',
        name: 'network',
        component: NetworkPage,
    },
    {
        path: '/',
        name: 'home',
        component: MainLayout,
    }
]

const router = createRouter({
    history: createWebHistory(import.meta.env.BASE_URL),  // 使用 WebHistory 模式
    routes,
})

export default router
